#!/bin/sh
# Sets the login password from SHOTS_PASSWORD (generated by the capture
# script, never committed), regenerates host keys per container, then runs sshd.
set -eu
: "${SHOTS_PASSWORD:?set SHOTS_PASSWORD}"
echo "fcoury:${SHOTS_PASSWORD}" | chpasswd
echo "${SHOTS_ROLE:-devbox}" > /etc/shots-role
ssh-keygen -A >/dev/null
exec /usr/sbin/sshd -D -e
